begin;
with j as (select * from jsonb_to_recordset($law7d0010$[{"code_id":"APK_RF","article_number":"82","version_date":"2002-07-24","article_text":"1. Для разъяснения возникающих при рассмотрении дела вопросов, требующих специальных знаний, арбитражный суд назначает экспертизу по ходатайству лица, участвующего в деле, или с согласия лиц, участвующих в деле. В случае, если назначение экспертизы предписано законом или предусмотрено договором либо необходимо для проверки заявления о фальсификации представленного доказательства либо если необходимо проведение дополнительной или повторной экспертизы, арбитражный суд может назначить экспертизу по своей инициативе.\n\n2. Круг и содержание вопросов, по которым должна быть проведена экспертиза, определяются арбитражным судом. Лица, участвующие в деле, вправе представить в арбитражный суд вопросы, которые должны быть разъяснены при проведении экспертизы. Отклонение вопросов, представленных лицами, участвующими в деле, суд обязан мотивировать.\n\n3. Лица, участвующие в деле, вправе ходатайствовать о привлечении в качестве экспертов указанных ими лиц или о проведении экспертизы в конкретном экспертном учреждении, заявлять отвод эксперту; ходатайствовать о внесении в определение о назначении экспертизы дополнительных вопросов, поставленных перед экспертом; давать объяснения эксперту; знакомиться с заключением эксперта или сообщением о невозможности дать заключение; ходатайствовать о проведении дополнительной или повторной экспертизы.\n\n4. О назначении экспертизы или об отклонении ходатайства о назначении экспертизы арбитражный суд выносит определение.\n\nВ определении о назначении экспертизы указываются основания для назначения экспертизы; фамилия, имя и отчество эксперта или наименование экспертного учреждения, в котором должна быть проведена экспертиза; вопросы, поставленные перед экспертом; материалы и документы, предоставляемые в распоряжение эксперта; срок, в течение которого должна быть проведена экспертиза и должно быть представлено заключение в арбитражный суд.\n\nВ определении также указывается на предупреждение эксперта об уголовной ответственности за дачу заведомо ложного заключения.","article_title":"Статья 82. Назначение экспертизы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"51e43caba430569ce614804f71dcb3479b5191537a0e2f29fc0683cb32d5fc00"},{"code_id":"APK_RF","article_number":"83","version_date":"2002-07-24","article_text":"1. Экспертиза проводится государственными судебными экспертами по поручению руководителя государственного судебно-экспертного учреждения и иными экспертами из числа лиц, обладающих специальными знаниями, в соответствии с федеральным законом.\n\nПроведение экспертизы может быть поручено нескольким экспертам.\n\n2. Лица, участвующие в деле, могут присутствовать при проведен\n\nии экспертизы, за исключением случаев, если такое присутствие способно помешать нормальной работе экспертов, но не вправе вмешиваться в ход исследований.\n\n3. При составлении экспертом заключения и на стадии совещания экспертов и формулирования выводов, если судебная экспертиза проводится комиссией экспертов, присутствие участников арбитражного процесса не допускается.","article_title":"Статья 83. Порядок проведения экспертизы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e6ac255919a254e3581369e5e9e2e75ee7cdb7da263687fdc3fb51974aa31cc"},{"code_id":"APK_RF","article_number":"84","version_date":"2002-07-24","article_text":"1. Комиссионная экспертиза проводится не менее чем двумя экспертами одной специальности. Комиссионный характер экспертизы определяется арбитражным судом.\n\n2. В случае, если по результатам проведенных исследований мнения экспертов по поставленным вопросам совпадают, экспертами составляется единое заключение. В случае возникновения разногласий каждый из экспертов, участвовавших в проведении экспертизы, дает отдельное заключение по вопросам, вызвавшим разногласия экспертов.","article_title":"Статья 84. Комиссионная экспертиза","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b424742e448c83444477f8d2339107dfec844b561542a4f698d0fc7753aec85e"},{"code_id":"APK_RF","article_number":"85","version_date":"2002-07-24","article_text":"1. Комплексная экспертиза проводится не менее чем двумя экспертами разных специальностей.\n\n2. В заключении экспертов указывается, какие исследования и в каком объеме провел каждый эксперт, какие факты он установил и к каким выводам пришел. Каждый эксперт, участвовавший в проведении комплексной экспертизы, подписывает ту часть заключения, которая содержит описание проведенных им исследований, и несет за нее ответственность.\n\n3. Общий вывод делают эксперты, компетентные в оценке полученных результатов и формулировании данного вывода. В случае возникновения разногласий между экспертами результаты исследований оформляются в соответствии с частью 2 статьи 84 настоящего Кодекса.","article_title":"Статья 85. Комплексная экспертиза","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"096ea07a2d3023dd361e84e69a2c4dc54aec2ee74854e38eb92f666cbdcec83f"},{"code_id":"APK_RF","article_number":"86","version_date":"2002-07-24","article_text":"1. На основании проведенных исследований и с учетом их результатов эксперт от своего имени или комиссия экспертов дает заключение в письменной форме и подписывает его.\n\n2. В заключении эксперта или комиссии экспертов должны быть отражены:\n\n1) время и место проведения судебной экспертизы;\n\n2) основания для проведения судебной экспертизы;\n\n3) сведения о государственном судебно-экспертном учреждении, об эксперте (фамилия, имя, отчество, образование, специальность, стаж работы, ученая степень и ученое звание, занимаемая должность), которым поручено проведение судебной экспертизы;\n\n4) записи о предупреждении эксперта в соответствии с законодательством Российской Федерации об уголовной ответственности за дачу заведомо ложного заключения;\n\n5) вопросы, поставленные перед экспертом или комиссией экспертов;\n\n6) объекты исследований и материалы дела, предоставленные эксперту для проведения судебной экспертизы;\n\n7) содержание и результаты исследований с указанием примененных методов;\n\n8) оценка результатов исследований, выводы по поставленным вопросам и их обоснование;\n\n9) иные сведения в соответствии с федеральным законом.\n\nМатериалы и документы, иллюстрирующие заключение эксперта или комиссии экспертов, прилагаются к заключению и служат его составной частью.\n\nЕсли эксперт при проведении экспертизы установит обстоятельства, которые имеют значение для дела и по поводу которых ему не были поставлены вопросы, он вправе включить выводы об этих обстоятельствах в свое заключение.\n\n3. Заключение эксперта оглашается в судебном заседании и исследуется наряду с другими доказательствами по делу.\n\nПо ходатайству лица, участвующего в деле, или по инициативе арбитражного суда эксперт может быть вызван в судебное заседание.\n\nЭксперт после оглашения его заключения вправе дать по нему необходимые пояснения, а также обязан ответить на дополнительные вопросы лиц, участвующих в деле, и суда. Ответы эксперта на дополнительные вопросы заносятся в протокол судебного заседания.","article_title":"Статья 86. Заключение эксперта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4879217535ae09b5370efb89c1fa0b02b0a7ce983a187b82f3d1fdd2779b7951"},{"code_id":"APK_RF","article_number":"87","version_date":"2002-07-24","article_text":"1. При недостаточной ясности или полноте заключения эксперта, а также при возникновении вопросов в отношении ранее исследованных обстоятельств дела может быть назначена дополнительная экспертиза, проведение которой поручается тому же или другому эксперту.\n\n2. В случае возникновения сомнений в обоснованности заключения эксперта или наличия противоречий в выводах эксперта или комиссии экспертов по тем же вопросам может быть назначена повторная экспертиза, проведение которой поручается другому эксперту или другой комиссии экспертов.","article_title":"Статья 87. Дополнительная и повторная экспертизы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"646bde5316b1de8b39d438a0829644aff0947d91bf0fd1b6d2d6364fc0f82139"},{"code_id":"APK_RF","article_number":"87.1","version_date":"2002-07-24","article_text":"1. В целях получения разъяснений, консультаций и выяснения профессионального мнения лиц, обладающих теоретическими и практическими познаниями по существу разрешаемого арбитражным судом спора, арбитражный суд может привлекать специалиста.\n\nСоветники аппарата специализированного арбитражного суда, обладающие квалификацией, соответствующей специализации суда, могут привлекаться в качестве специалистов.\n\n2. Специалист дает консультацию добросовестно и беспристрастно исходя из профессиональных знаний и внутреннего убеждения.\n\nКонсультация дается в устной форме без проведения специальных исследований, назначаемых на основании определения суда.\n\n3. В целях получения разъяснений и дополнений по оказанной консультации специалисту могут быть заданы вопросы судом и лицами, участвующими в деле.\n\n(Дополнение статьей - Федеральный закон от 08.12.2011 № 422-ФЗ)","article_title":"Статья 87.1. Консультация специалиста","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f96f93acf8b220773d4dd51b1ef859f08be8dc5af9977a146fa6b84829f95cf2"},{"code_id":"APK_RF","article_number":"88","version_date":"2002-07-24","article_text":"1. По ходатайству лица, участвующего в деле, арбитражный суд вызывает свидетеля для участия в арбитражном процессе.\n\nЛицо, ходатайствующее о вызове свидетеля, обязано указать, какие обстоятельства, имеющие значение для дела, может подтвердить свидетель, и сообщить суду его фамилию, имя, отчество и место жительства.\n\n2. Арбитражный суд по своей инициативе может вызвать в качестве свидетеля лицо, участвовавшее в составлении документа, исследуемого судом как письменное доказательство, либо в создании или изменении предмета, исследуемого судом как вещественное доказательство.\n\n3. Свидетель сообщает известные ему сведения устно. По предложению суда свидетель может изложить показания, данные устно, в письменной форме.\n\nПоказания свидетеля, изложенные в письменной форме, приобщаются к материалам дела.\n\n4. Не являются доказательствами сведения, сообщаемые свидетелем, если он не может указать источник своей осведомленности.","article_title":"Статья 88. Свидетельские показания","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2deb20fc5cb17a9d91557eaaab29c91d42d16a5bc8bca732dc436c0c4203baf"},{"code_id":"APK_RF","article_number":"89","version_date":"2002-07-24","article_text":"1. Иные документы и материалы допускаются в качестве доказательств, если содержат сведения об обстоятельствах, имеющих значение для правильного рассмотрения дела.\n\n2. Иные документы и материалы могут содержать сведения, зафиксированные как в письменной, так и в иной форме. К ним могут относиться материалы фото- и киносъемки, аудио- и видеозаписи и иные носители информации, полученные, истребованные или представленные в порядке, установленном настоящим Кодексом.\n\n3. Документы приобщаются к материалам дела и хранятся в арбитражном суде в течение всего срока хранения дела. По ходатайству лица, от которого они были получены, документы или их копии могут быть ему возвращены.","article_title":"Статья 89. Иные документы и материалы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af81140a0d9c31aefe891973e80ef57200bb7faece36ccaa90ca869fac9a3372"},{"code_id":"APK_RF","article_number":"9","version_date":"2002-07-24","article_text":"1. Судопроизводство в арбитражном суде осуществляется на основе состязательности.\n\n2. Лица, участвующие в деле, вправе знать об аргументах друг друга до начала судебного разбирательства. Каждому лицу, участвующему в деле, гарантируется право представлять доказательства арбитражному суду и другой стороне по делу, обеспечивается право заявлять ходатайства, высказывать свои доводы и соображения, давать объяснения по всем возникающим в ходе рассмотрения дела вопросам, связанным с представлением доказательств. Лица, участвующие в деле, несут риск наступления последствий совершения или несовершения ими процессуальных действий.\n\n3. Арбитражный суд, сохраняя независимость, объективность и беспристрастность, осуществляет руководство процессом, разъясняет лицам, участвующим в деле, их права и обязанности, предупреждает о последствиях совершения или несовершения ими процессуальных действий, оказывает содействие в реализации их прав, создает условия для всестороннего и полного исследования доказательств, установления фактических обстоятельств и правильного применения законов и иных нормативных правовых актов при рассмотрении дела.","article_title":"Статья 9. Состязательность","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"47a440d6cb46dc5863411e60c1f1a4e4b23dbbced839c7b8399e555afdd673a4"},{"code_id":"APK_RF","article_number":"91","version_date":"2002-07-24","article_text":"1. Обеспечительными мерами могут быть:\n\n1) наложение ареста на денежные средства (в том числе денежные средства, которые будут поступать на банковский счет) или иное имущество, принадлежащие ответчику и находящиеся у него или других лиц; (В редакции Федерального закона от 19.07.2009 № 205-ФЗ)\n\n2) запрещение ответчику и другим лицам совершать определенные действия, касающиеся предмета спора;\n\n3) возложение на ответчика обязанности совершить определенные действия в целях предотвращения порчи, ухудшения состояния спорного имущества;\n\n4) передача спорного имущества на хранение истцу или другому лицу;\n\n5) приостановление взыскания по оспариваемому истцом исполнительному или иному документу, взыскание по которому производится в бесспорном (безакцептном) порядке;\n\n6) приостановление реализации имущества в случае предъявления иска об освобождении имущества от ареста.\n\nАрбитражным судом могут быть приняты иные обеспечительные меры, а также одновременно может быть принято несколько обеспечительных мер.\n\n2. Обеспечительные меры должны быть соразмерны заявленному требованию.","article_title":"Статья 91. Обеспечительные меры","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cb39c4b7209b7c7a567c508ca450e1940637ec43698fee4935a888e946c01957"},{"code_id":"APK_RF","article_number":"92","version_date":"2002-07-24","article_text":"1. Заявление об обеспечении иска может быть подано в арбитражный суд одновременно с исковым заявлением или в процессе производства по делу до принятия судебного акта, которым заканчивается рассмотрение дела по существу. Ходатайство об обеспечении иска может быть изложено в исковом заявлении.\n\nЗаявление об обеспечении иска, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В заявлении об обеспечении иска должны быть указаны:\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименования истца и ответчика, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) предмет спора;\n\n4) размер имущественных требований;\n\n5) обоснование причины обращения с заявлением об обеспечении иска;\n\n6) обеспечительная мера, которую просит принять истец;\n\n7) перечень прилагаемых документов.\n\nВ заявлении об обеспечении иска могут быть также указаны встречное обеспечение и иные сведения, в том числе номера телефонов, факсов, адреса электронной почты лиц, участвующих в деле.\n\n3. Заявление об обеспечении иска подписывается лицом, участвующим в деле, или его представителем.\n\nК заявлению, подписанному представителем, прилагается доверенность или иной подтверждающий полномочия на его подписание документ.\n\n4. В случае, если ходатайство об обеспечении иска изложено в исковом заявлении, в этом ходатайстве должны быть указаны сведения, предусмотренные пунктами 5 и 6 части 2 настоящей статьи.\n\n5. К заявлению стороны третейского разбирательства об обеспечении иска прилагаются заверенная председателем постоянно действующего третейского суда копия искового заявления, принятого к рассмотрению третейским судом, или нотариально удостоверенная копия такого заявления и заверенная надлежащим образом копия соглашения о третейском разбирательстве.\n\n6. К заявлению об обеспечении иска, если оно в соответствии с настоящим Кодексом оплачивается государственной пошлиной, прилагается документ, подтверждающий ее уплату.","article_title":"Статья 92. Заявление об обеспечении иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f3ccc31017fa785ee353b8d03ba466102ac68c0651d98c8ea03eb161a83c7e9"},{"code_id":"APK_RF","article_number":"93","version_date":"2002-07-24","article_text":"Копия определения об отказе в обеспечении иска направляется лицу, обратившемуся с заявлением об обеспечении иска.","article_title":"Статья 93. Порядок рассмотрения заявления об обеспечении иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46a1d81de5c9c39ed81a7be93ef32e5d66289e0747ff9aa55c5a902102eaa11c"},{"code_id":"APK_RF","article_number":"94","version_date":"2002-07-24","article_text":"1. Арбитражный суд, допуская обеспечение иска, по ходатайству ответчика может потребовать от обратившегося с заявлением об обеспечении иска лица или предложить ему по собственной инициативе предоставить обеспечение возмещения возможных для ответчика убытков (встречное обеспечение) путем внесения на депозитный счет суда денежных средств в размере, предложенном судом, либо предоставления банковской гарантии, поручительства или иного финансового обеспечения на ту же сумму. Размер встречного обеспечения может быть установлен в пределах имущественных требований истца, указанных в его заявлении, а также суммы процентов от этих требований. Размер встречного обеспечения не может быть менее половины размера имущественных требований.\n\n2. Встречное обеспечение может быть предоставлено также ответчиком взамен мер по обеспечению иска о взыскании денежной суммы путем внесения на депозитный счет арбитражного суда денежных средств в размере требований истца.\n\n3. О встречном обеспечении арбитражный суд выносит определение не позднее следующего дня после дня поступления в суд заявления об обеспечении иска.\n\nВ определении указываются размер встречного обеспечения и срок его предоставления, который не может превышать пятнадцать дней со дня вынесения определения.\n\nКопия определения направляется лицам, участвующим в деле, не позднее следующего дня после дня вынесения определения.\n\nОпределение о встречном обеспечении может быть обжаловано.\n\n4. В случае вынесения определения о встречном обеспечении арбитражный суд не рассматривает заявление об обеспечении иска до представления в арбитражный суд документа, подтверждающего произведенное встречное обеспечение.\n\n5. При представлении в арбитражный суд документа, подтверждающего произведенное встречное обеспечение, или по истечении указанного в определении суда срока его представления арбитражный суд не позднее следующего дня после дня поступления такого документа рассматривает заявление об обеспечении иска в порядке, установленном статьей 93 настоящего Кодекса.\n\n6. Неисполнение лицом, ходатайствующим об обеспечении иска, определения арбитражного суда о встречном обеспечении в срок, указанный в определении, может быть основанием для отказа в обеспечении иска.\n\n7. Представление ответчиком документа, подтверждающего произведенное им встречное обеспечение, является основанием для отказа в обеспечении иска или отмены обеспечения иска.","article_title":"Статья 94. Встречное обеспечение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2209bebdf56a3d45417f2fa7475c221382572e024a7104c1b43f6034b7df8e56"},{"code_id":"APK_RF","article_number":"95","version_date":"2002-07-24","article_text":"1. По ходатайству истца или ответчика допускается замена одной обеспечительной меры другой.\n\n2. Вопрос о замене одной обеспечительной меры другой разрешается арбитражным судом в судебном заседании не позднее следующего дня после дня поступления в суд ходатайства о замене одной обеспечительной меры другой по правилам, предусмотренным настоящим Кодексом.","article_title":"Статья 95. Замена одной обеспечительной меры другой","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e69c5a4f8e3d23a408b17bf1ee0a28164289779ccb778fad29a3bc4ea1fa7bd3"},{"code_id":"APK_RF","article_number":"96","version_date":"2002-07-24","article_text":"арантии, поручительства или иного финансового обеспечения на ту же сумму, он вправе обратиться в арбитражный суд, рассматривающий дело, с ходатайством об отмене обеспечительных мер, которое рассматривается в соответствии со статьей 93 настоящего Кодекса.","article_title":"Статья 96. Исполнение определения арбитражного суда об обеспечении иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93317ac8ebb3c546ca3d58661ba1f02620ecf4b300da3f1ca796cfaf73ca94df"},{"code_id":"APK_RF","article_number":"97","version_date":"2002-07-24","article_text":"1. Обеспечение иска по ходатайству лица, участвующего в деле, может быть отменено арбитражным судом, рассматривающим дело.\n\n2. Вопрос об отмене обеспечения иска разрешается в судебном заседании в пятидневный срок со дня поступления заявления в арбитражный суд в порядке, предусмотренном статьей 93 настоящего Кодекса.\n\n3. В случае представления ответчиком документа, подтверждающего произведенное им встречное обеспечение, вопрос об отмене обеспечения иска рассматривается арбитражным судом не позднее следующего дня после дня представления указанного документа.\n\n4. По результатам рассмотрения ходатайства об отмене обеспечения иска выносится определение.\n\nКопии определения направляются лицам, участвующим в деле, не позднее следующего дня после дня его вынесения. Копии определения об отмене обеспечения иска в зависимости от вида принятых мер направляются также в государственные органы, иные органы, осуществляющие государственную регистрацию имущества или прав на него.\n\n5. Определения арбитражного суда об отмене обеспечения иска и об отказе в отмене обеспечения иска могут быть обжалованы.\n\n6. Отказ в отмене обеспечения иска не препятствует повторному обращению с таким же ходатайством при появлении новых обстоятельств, обосновывающих необходимость отмены обеспечения иска.","article_title":"Статья 97. Отмена обеспечения иска арбитражным судом","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"89cc4cbcb37624bdcef2e841fa61594329ae258c34f3ce1da0eff923811bec99"},{"code_id":"APK_RF","article_number":"98","version_date":"2002-07-24","article_text":"1. Ответчик и другие лица, чьи права и (или) законные интересы нарушены обеспечением иска, после вступления в законную силу судебного акта арбитражного суда об отказе в удовлетворении иска вправе требовать от лица, по заявлению которого были приняты обеспечительные меры, возмещения убытков в порядке и в размере, которые предусмотрены гражданским законодательством, или выплаты компенсации.\n\n2. Размер компенсации определяется судом в зависимости от характера нарушения и иных обстоятельств дела с учетом требований разумности и справедливости по спорам, указанным в статье 2251 настоящего Кодекса, в пределах от десяти тысяч до одного миллиона рублей, по другим спорам - от одной тысячи до одного миллиона рублей.\n\n3. Иск о возмещении убытков или выплате компенсации предъявляется в арбитражный суд, рассматривавший дело, по которому принимались обеспечительные меры.\n\n4. Правила, установленные настоящей статьей, применяются в случаях оставления иска без рассмотрения по основаниям, предусмотренным пунктами 1 и 2 части 1 статьи 148 настоящего Кодекса, а также в случаях прекращения производства по делу по основаниям, предусмотренным пунктами 2 - 4 части 1 статьи 150 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 98. Убытки и компенсации в связи с обеспечением иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e9071162f82f65013de2cb77792a4b8c7d45bdf36fc372f8c0c0e72b346005cf"},{"code_id":"APK_RF","article_number":"99","version_date":"2002-07-24","article_text":"1. Арбитражный суд по заявлению организации или гражданина вправе принять предварительные обеспечительные меры, направленные на обеспечение имущественных интересов заявителя до предъявления иска.\n\nЗаявление об обеспечении имущественных интересов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n11. Арбитражный суд вправе по заявлению Банка России, поданному в случае установления им отрицательного значения величины собственных средств (капитала) кредитной организации, страховой организации, негосударственного пенсионного фонда, принять предварительные обеспечительные меры, предусматривающие наложение ареста на денежные средства, ценные бумаги и недвижимое имущество лиц, контролирующих кредитную организацию, страховую организацию, негосударственный пенсионный фонд, до подачи заявления о привлечении указанных лиц к субсидиарной ответственности, ответственности в форме возмещения убытков в соответствии с Федеральным законом от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве)\". Арбитражный суд выносит определение об оставлении заявления Банка России о принятии предварительных обеспечительных мер без движения, если при рассмотрении вопроса о принятии данного заявления к производству установит, что оно не содержит сведений, позволяющих с минимально необходимой степенью достоверности сделать обоснованные предположения о том, что ответчик, указанный в заявлении, является или являлся контролирующим лицом. Рассмотрение судом дела об оспаривании включения лица в перечень контролирующих кредитную организацию лиц в соответствии со статьей 576 Федерального закона от 10 июля 2002 года № 86-ФЗ \"О Центральном банке Российской Федерации (Банке России)\", перечень контролирующих страховую организацию лиц или перечень контролирующих негосударственный пенсионный фонд лиц в соответствии со статьей 767-1 Федерального закона от 10 июля 2002 года № 86-ФЗ \"О Центральном банке Российской Федерации (Банке России)\" не препятствует принятию арбитражным судом заявления Банка России о принятии предварительных обеспечительных мер, рассмотрению данного заявления и принятию предварительных обеспечительных мер в соответствии с настоящей частью.\n\nРазмер предварительных обеспечительных мер, принимаемых арбитражным судом по заявлению Банка России в соответствии с настоящей частью, не может превышать величину денежных средств, необходимых для восполнения собственных средств (капитала) кредитной организации, страховой организации, негосударственного пенсионного фонда в целях приведения их к величине, необходимой и достаточной для выполнения указанными организациями требований федеральных законов и нормативных актов Банка России.\n\n(Дополнение частью - Федеральный закон от 24.02.2021 № 23-ФЗ)\n\n2. Предварительные обеспечительные меры принимаются арбитражным судом по правилам, предусмотренным настоящей главой, с особенностями, установленными настоящей статьей.\n\nВ случае непредставления указанного документа арбитражный суд вправе предложить заявителю предоставить встречное обеспечение в соответствии со статьей 94 настоящего Кодекса и оставляет заявление об обеспечении имущественных интересов без движения по правилам статьи 128 настоящего Кодекса до представления документа, подтверждающего произведенное встречное обеспечение.\n\nПри подаче Банком России заявления о принятии предварительных обеспечительных мер в соответствии с частью 11 настоящей статьи предоставления встречного обеспечения в соответствии со статьей 94 настоящего Кодекса не требуется. (Дополнение абзацем - Федеральный закон от 24.02.2021 № 23-ФЗ)\n\nВ случае, если по требованию, в связи с которым подано заявление об обеспечении имущественных интересов, в силу закона обязательно соблюдение претензионного или иного досудебного порядка урегулирования спора, в определении устанавливаются срок для направления претензии (требования) другой стороне, не превышающий пятнадцати дней со дня вынесения определения, и срок для подачи искового заявления по такому требованию, не превышающий пяти дней со дня истечения установленного законом или договором срока для принятия сторонами мер по досудебному урегулированию в соответствии с частью 5 статьи 4 настоящего Кодекса. Если указанный порядок не является обязательным, в определении устанавливается срок, не превышающий пятнадцати дней со дня вынесения определения, для подачи искового заявления по требованию, в связи с которым судом приняты меры по обеспечению имущественных интересов заявителя.\n\nПри подаче Банком России заявления о принятии предварительных обеспечительных мер в соответствии с частью 11 настоящей статьи в определении об обеспечении имущественных интересов устанавливается срок, не превышающий тридцати дней со дня вынесения определения, для подачи искового заявления по требованию, в связи с которым судом приняты меры по обеспечению имущественных интересов Банка России. (Дополнение абзацем - Федеральный закон от 24.02.2021 № 23-ФЗ)\n\n(Часть в редакции Федерального закона от 01.07.2017 № 147-ФЗ)\n\nОб отмене обеспечения имущественных интересов выносится определение.\n\nКопии определения направляются заявителю и иным заинтересованным лицам не позднее следующего дня после дня вынесения определения.\n\nЛицо, в отношении имущества которого были приняты предварительные обеспечительные меры в соответствии с частью 11 настоящей статьи, вправе требовать по своему выбору от Банка России возмещения убытков или выплаты компенсации в порядке, предусмотренном статьей 98 настоящего Кодекса, если Банком России в установленный судом срок не было подано исковое заявление по требованию, в связи с которым арбитражным судом были приняты меры по обеспечению имущественных интересов Банка России, или если вступившим в законную силу судебным актом арбитражного суда в иске было отказано. (Дополнение абзацем - Федеральный закон от 24.02.2021 № 23-ФЗ)","article_title":"Статья 99. Предварительные обеспечительные меры","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"31e045cf3384e7aa6090b6a5d438d3384d694e1d5178707655984ded1b0a11f2"},{"code_id":"BK_RF","article_number":"1","version_date":"1998-07-31","article_text":"1. К бюджетным правоотношениям относятся:\n\nотношения,  возникающие между субъектами бюджетных правоотношений в процессе формирования доходов и осуществления расходов бюджетов бюджетной системы Российской Федерации,  осуществления государственных (муниципальных)  заимствований,  регулирования государственного (муниципального)  долга; (В редакции федеральных законов от 26.04.2007 № 63-ФЗ,  от 02.08.2019 № 278-ФЗ)\n\nотношения,  возникающие между субъектами бюджетных правоотношений в процессе составления и рассмотрения проектов бюджетов бюджетной системы Российской Федерации,  утверждения и исполнения бюджетов бюджетной системы Российской Федерации,  контроля за их исполнением,  осуществления бюджетного учета,  составления,  рассмотрения и утверждения бюджетной отчетности. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n2. Настоящий Кодекс устанавливает правовой статус участников бюджетного процесса,  правовые основы казначейского сопровождения,  применения бюджетных мер принуждения за совершение бюджетных нарушений. (В редакции федеральных законов от 26.07.2019 № 199-ФЗ,  от 01.07.2021 № 244-ФЗ)","article_title":"Статья 1. Правоотношения,  регулируемые Бюджетным кодексом Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"33dc8ff9a180d26000babe6e25ef00221db4bfd1d86d1334b82a1d671b1f7beb"},{"code_id":"BK_RF","article_number":"10","version_date":"1998-07-31","article_text":"К бюджетам бюджетной системы Российской Федерации относятся:\n\nфедеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации;\n\nбюджеты субъектов Российской Федерации и бюджеты территориальных государственных внебюджетных фондов;\n\nместные бюджеты,  в том числе:\n\nбюджеты муниципальных районов,  бюджеты муниципальных округов,  бюджеты городских округов,  бюджеты городских округов с внутригородским делением,  бюджеты внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции федеральных законов от 22.10.2014 № 311-ФЗ,  от 29.11.2014 № 383-ФЗ,  от 01.10.2020 № 311-ФЗ)\n\nбюджеты городских и сельских поселений,  бюджеты внутригородских районов. (В редакции Федерального закона от 29.11.2014 № 383-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 10. Структура бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50494720d2362ba6d723ff09eb7145444152da6beb325f7d64175f0262c9e23f"},{"code_id":"BK_RF","article_number":"11","version_date":"1998-07-31","article_text":"Федеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации разрабатываются и утверждаются в форме федеральных законов,  бюджеты субъектов Российской Федерации и бюджеты территориальных государственных внебюджетных фондов разрабатываются и утверждаются в форме законов субъектов Российской Федерации,  местные бюджеты разрабатываются и утверждаются в форме муниципальных правовых актов представительных органов муниципальных образований.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 11. Правовая форма бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"568a143c4a92f91048daaeec89ce8dade0b130ac7d6e6492a015397159a11df1"},{"code_id":"BK_RF","article_number":"12","version_date":"1998-07-31","article_text":"Финансовый год соответствует календарному году и длится с 1 января по 31 декабря.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 12. Финансовый год","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1c789ef65f4a656d5e053804f16c3fab7d953f77736b84d55fb83e0ca9c3b4c9"},{"code_id":"BK_RF","article_number":"13","version_date":"1998-07-31","article_text":"Федеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации предназначены для исполнения расходных обязательств Российской Федерации.\n\nИспользование федеральными органами государственной власти иных форм образования и расходования денежных средств,  предназначенных для исполнения расходных обязательств Российской Федерации,  не допускается.\n\nФедеральный бюджет и свод консолидированных бюджетов субъектов Российской Федерации (без учета межбюджетных трансфертов между этими бюджетами)  образуют консолидированный бюджет Российской Федерации.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 13. Федеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d22c29391587f6764649cb0c09669f4c440cfdfbce8ff5ced15e6d72eae1ed51"},{"code_id":"BK_RF","article_number":"14","version_date":"1998-07-31","article_text":"Каждый субъект Российской Федерации имеет собственный бюджет и бюджет территориального государственного внебюджетного фонда.\n\nБюджет субъекта Российской Федерации (региональный бюджет)  и бюджет территориального государственного внебюджетного фонда предназначены для исполнения расходных обязательств субъекта Российской Федерации.\n\nИспользование органами государственной власти субъектов Российской Федерации иных форм образования и расходования денежных средств для исполнения расходных обязательств субъектов Российской Федерации не допускается.\n\nВ бюджетах субъектов Российской Федерации в соответствии с бюджетной классификацией Российской Федерации раздельно предусматриваются средства,  направляемые на исполнение расходных обязательств субъектов Российской Федерации,  возникающих в связи с осуществлением органами государственной власти субъектов Российской Федерации полномочий по предметам ведения субъектов Российской Федерации и полномочий по предметам совместного ведения,  указанных в частях 1 и 5 статьи 44 Федерального закона от 21 декабря 2021 года № 414-ФЗ \"Об общих принципах организации публичной власти в субъектах Российской Федерации\",  и расходных обязательств субъектов Российской Федерации,  осуществляемых за счет субвенций из федерального бюджета. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nБюджет субъекта Российской Федерации и свод бюджетов муниципальных образований,  входящих в состав субъекта Российской Федерации (без учета межбюджетных трансфертов между этими бюджетами) ,  образуют консолидированный бюджет субъекта Российской Федерации.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 14. Бюджет субъекта Российской Федерации и бюджет территориального государственного внебюджетного фонда","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d503066f4ae75d90dfc811e75e37301d9bf35b64fdc03c0a78d1bc1f8d042ef3"},{"code_id":"BK_RF","article_number":"15","version_date":"1998-07-31","article_text":"Каждое муниципальное образование имеет собственный бюджет.\n\nБюджет муниципального образования (местный бюджет)  предназначен для исполнения расходных обязательств муниципального образования.\n\nИспользование органами местного самоуправления иных форм образования и расходования денежных средств для исполнения расходных обязательств муниципальных образований не допускается.\n\nВ местных бюджетах в соответствии с бюджетной классификацией Российской Федерации раздельно предусматриваются средства,  направляемые на исполнение расходных обязательств муниципальных образований,  возникающих в связи с осуществлением органами местного самоуправления полномочий по вопросам местного значения,  и расходных обязательств муниципальных образований,  исполняемых за счет субвенций из других бюджетов бюджетной системы Российской Федерации для осуществления отдельных государственных полномочий.\n\nБюджет муниципального района (районный бюджет)  и свод бюджетов городских и сельских поселений,  входящих в состав муниципального района (без учета межбюджетных трансфертов между этими бюджетами) ,  образуют консолидированный бюджет муниципального района.\n\nВ качестве составной части бюджетов городских,  сельских поселений,  внутригородских районов,  муниципальных районов (в отношении населенных пунктов,  других территорий,  расположенных на межселенных территориях) ,  муниципальных округов,  городских округов,  внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя могут быть предусмотрены сметы доходов и расходов отдельных населенных пунктов,  других территорий,  не являющихся муниципальными образованиями. (В редакции Федерального закона от 01.10.2020 № 311-ФЗ)\n\nБюджет городского округа с внутригородским делением и свод бюджетов внутригородских районов,  входящих в состав городского округа с внутригородским делением (без учета межбюджетных трансфертов между этими бюджетами) ,  образуют консолидированный бюджет городского округа с внутригородским делением. (Дополнение частью - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 15. Местный бюджет","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"67929442ae2ee61570e1e77f58603a00e1a2fd979125ba703e4fc46550b5dded"},{"code_id":"BK_RF","article_number":"16","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 16.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"17","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 17.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"18","version_date":"1998-07-31","article_text":"1. Бюджетная классификация Российской Федерации является группировкой доходов,  расходов и источников финансирования дефицитов бюджетов бюджетной системы Российской Федерации,  используемой для составления и исполнения бюджетов,  а также группировкой доходов,  расходов и источников финансирования дефицитов бюджетов и (или)  операций сектора государственного управления,  используемой для ведения бюджетного (бухгалтерского)  учета,  составления бюджетной (бухгалтерской)  и иной финансовой отчетности,  обеспечивающей сопоставимость показателей бюджетов бюджетной системы Российской Федерации. (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\n2. Определение принципов назначения,  структуры,  порядка формирования и применения кодов бюджетной классификации Российской Федерации,  а также присвоение кодов составным частям бюджетной классификации Российской Федерации,  которые в соответствии с настоящим Кодексом являются едиными для бюджетов бюджетной системы Российской Федерации,  осуществляются Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 настоящей статьи. (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\n3. Утверждение или изменение нормативных правовых актов Министерства финансов Российской Федерации,  регулирующих вопросы,  указанные в пункте 2 настоящей статьи,  пункте 6,  абзацах третьем и четвертом пункта 9 статьи 20,  абзацах четвертом - шестом пункта 4,  пунктах 7 и 8 статьи 21,  абзацах втором и третьем пункта 5 статьи 23,  пунктах 3 - 5 статьи 231 настоящего Кодекса,  осуществляется исключительно в связи с составлением или принятием федеральных законов о федеральном бюджете или о внесении изменений в федеральный закон о федеральном бюджете,  но не более одного раза в связи с составлением и не более одного раза в связи с принятием такого федерального закона,  за исключением случаев,  установленных в абзаце втором пункта 6,  абзаце пятом пункта 9 статьи 20,  пункте 9 статьи 21 и абзаце четвертом пункта 5 статьи 23 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)  (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\n4. Нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в пункте 2 настоящей статьи,  пункте 6 и абзаце третьем пункта 9 статьи 20,  пунктах 7 и 8 статьи 21,  абзаце втором пункта 5 статьи 23,  пунктах 3 - 5 статьи 231 настоящего Кодекса,  включая изменения в них,  обратной силы не имеют и применяются к отношениям,  возникшим не ранее дня их вступления в силу,  за исключением случаев,  установленных пунктом 9 статьи 21 и абзацем четвертым пункта 5 статьи 23 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 18. Бюджетная классификация Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bcf1cb086a0855625535868452798b9d13d91c3560c1d6951ebf9d66aa267306"},{"code_id":"BK_RF","article_number":"19","version_date":"1998-07-31","article_text":"Бюджетная классификация Российской Федерации включает:\n\nклассификацию доходов бюджетов;\n\nклассификацию расходов бюджетов;\n\nклассификацию источников финансирования дефицитов бюджетов;\n\nклассификацию операций публично-правовых образований (далее - классификация операций сектора государственного управления) .\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 19. Состав бюджетной классификации Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4cda38fdcdf6a4291ae9def7d33e8761e6a45941d159ec3385e1b5bbb22a3419"},{"code_id":"BK_RF","article_number":"2","version_date":"1998-07-31","article_text":"Бюджетное законодательство Российской Федерации состоит из настоящего Кодекса и принятых в соответствии с ним федеральных законов о федеральном бюджете,  федеральных законов о бюджетах государственных внебюджетных фондов Российской Федерации,  законов субъектов Российской Федерации о бюджетах субъектов Российской Федерации,  законов субъектов Российской Федерации о бюджетах территориальных государственных внебюджетных фондов,  муниципальных правовых актов представительных органов муниципальных образований о местных бюджетах (далее - закон (решение)  о бюджете) ,  иных федеральных законов,  законов субъектов Российской Федерации и муниципальных правовых актов представительных органов муниципальных образований,  регулирующих правоотношения,  указанные в статье 1 настоящего Кодекса.\n\nФедеральные законы,  законы субъектов Российской Федерации,  муниципальные правовые акты представительных органов муниципальных образований,  предусмотренные частью первой настоящей статьи,  не могут противоречить настоящему Кодексу.\n\nВнесение изменений в Бюджетный кодекс Российской Федерации,  а также приостановление,  отмена и признание утратившими силу положений Бюджетного кодекса Российской Федерации осуществляются отдельными федеральными законами и не могут быть включены в тексты федеральных законов,  изменяющих (приостанавливающих,  отменяющих,  признающих утратившими силу)  другие законодательные акты Российской Федерации или содержащих самостоятельный предмет правового регулирования. (Дополнение частью - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 2. Структура бюджетного законодательства Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff9b76412fffd26b6534c1f5793eaa3c346ba8928eee1694573d7e7fed056498"},{"code_id":"BK_RF","article_number":"20","version_date":"1998-07-31","article_text":"1. Код классификации доходов бюджетов Российской Федерации состоит из:\n\n1)  кода главного администратора доходов бюджета;\n\n2)  кода вида доходов;\n\n3)  кода подвида доходов;\n\n4)  (Подпункт утратил силу - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n2. (Пункт утратил силу - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\n3. Код вида доходов включает группу,  подгруппу,  статью,  подстатью и элемент дохода.\n\n4. Едиными для бюджетов бюджетной системы Российской Федерации группами и подгруппами доходов бюджетов являются:\n\n1)  налоговые и неналоговые доходы:\n\nналоги на прибыль,  доходы;\n\nабзац; (Утратил силу - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nналоги на товары (работы,  услуги) ,  реализуемые на территории Российской Федерации;\n\nналоги на товары,  ввозимые на территорию Российской Федерации;\n\nналоги на совокупный доход;\n\nналоги на имущество;\n\nналоги,  сборы и регулярные платежи за пользование природными ресурсами;\n\nгосударственная пошлина;\n\nзадолженность и перерасчеты по отмененным налогам,  сборам и иным обязательным платежам;\n\nстраховые взносы на обязательное социальное страхование; (Дополнение абзацем - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nдоходы от внешнеэкономической деятельности;\n\nдоходы от использования имущества,  находящегося в государственной и муниципальной собственности;\n\nплатежи при пользовании природными ресурсами;\n\nдоходы от оказания платных услуг и компенсации затрат государства;\n\nдоходы от продажи материальных и нематериальных активов;\n\nадминистративные платежи и сборы;\n\nштрафы,  санкции,  возмещение ущерба;\n\nабзац; (Утратил силу - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nпоступления (перечисления)  по урегулированию расчетов между бюджетами бюджетной системы Российской Федерации; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\nпрочие неналоговые доходы;\n\n2)  безвозмездные поступления:\n\nбезвозмездные поступления от нерезидентов;\n\nбезвозмездные поступления от других бюджетов бюджетной системы Российской Федерации;\n\nбезвозмездные поступления от государственных (муниципальных)  организаций;\n\nбезвозмездные поступления от негосударственных организаций;\n\nбезвозмездные поступления от наднациональных организаций;\n\nпоступления (перечисления)  для осуществления возврата (зачета)  излишне уплаченных или излишне взысканных сумм налогов,  сборов и иных платежей,  а также сумм процентов за несвоевременное осуществление такого возврата и процентов,  начисленных на излишне взысканные суммы; (Дополнение абзацем - Федеральный закон от 31.07.2020 № 263-ФЗ)\n\nдоходы бюджетов бюджетной системы Российской Федерации от возврата остатков субсидий,  субвенций и иных межбюджетных трансфертов,  имеющих целевое назначение,  прошлых лет; (Дополнение абзацем - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nвозврат остатков субсидий,  субвенций и иных межбюджетных трансфертов,  имеющих целевое назначение,  прошлых лет; (Дополнение абзацем - Федеральный закон от 08.05.2010 № 83-ФЗ)\n\nпрочие безвозмездные поступления.\n\n5. Доходы,  указанные в абзацах втором,  четвертом - десятом подпункта 1 пункта 4 настоящей статьи,  являются налоговыми доходами бюджетов. Доходы,  указанные в абзацах одиннадцатом - двадцать втором подпункта 1 пункта 4 настоящей статьи,  являются неналоговыми доходами бюджетов. (В редакции федеральных законов от 24.07.2009 № 213-ФЗ; от 07.05.2013 № 104-ФЗ)\n\n6. Единый для бюджетов бюджетной системы Российской Федерации перечень статей и подстатей доходов бюджетов утверждается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\nВнесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзаце первом настоящего пункта,  осуществляется в связи с принятием федеральных законов и (или)  нормативных правовых актов  Правительства  Российской Федерации,  обусловливающих установление новых либо изменение действующих источников доходов федерального бюджета,  бюджетов государственных внебюджетных фондов Российской Федерации,  бюджетов субъектов Российской Федерации,  бюджетов территориальных государственных внебюджетных фондов и местных бюджетов. (Дополнение абзацем - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\n7. Код элемента доходов устанавливается в зависимости от полномочия по установлению и нормативному правовому регулированию налогов,  сборов и иных обязательных платежей,  других доходов бюджетов бюджетной системы Российской Федерации,  а также в зависимости от наличия прав требования к плательщикам по неналоговым доходам и безвозмездным поступлениям и соответствует бюджету бюджетной системы Российской Федерации.\n\n8. Едиными для бюджетов бюджетной системы Российской Федерации элементами доходов являются:\n\n1)  федеральный бюджет;\n\n2)  бюджеты субъектов Российской Федерации;\n\n3)  бюджеты муниципальных районов;\n\n31)  бюджеты муниципальных округов; (Дополнение подпунктом - Федеральный закон от 01.10.2020 № 311-ФЗ)\n\n4)  бюджеты городских округов;\n\n41)  бюджеты городских округов с внутригородским делением; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n5)  бюджеты внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\n6)  бюджеты городских поселений; (В редакции Федерального закона от 29.11.2014 № 383-ФЗ)\n\n61)  бюджеты сельских поселений; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n62)  бюджеты внутригородских районов; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n7)  бюджет Фонда пенсионного и социального страхования Российской Федерации; (В редакции  Федерального закона от 14.07.2022 № 264-ФЗ)\n\n8)  (Подпункт утратил силу  - Федеральный закон от 14.07.2022 № 264-ФЗ)\n\n9)  бюджет Федерального фонда обязательного медицинского страхования;\n\n10)  бюджеты территориальных фондов обязательного медицинского страхования.\n\n9. Для детализации поступлений по кодам классификации доходов применяется код подвида доходов.\n\nМинистерство финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса утверждает: (В редакции  федеральных законов от 22.10.2014 № 311-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\nобщие требования к порядку формирования перечня кодов подвидов доходов бюджетов бюджетной системы Российской Федерации; (Дополнение абзацем - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\nперечень кодов подвидов по видам доходов,  главными администраторами которых являются органы государственной власти (государственные органы)  Российской Федерации,  Центральный банк Российской Федерации,  органы управления государственными внебюджетными фондами Российской Федерации и (или)  находящиеся в их ведении казенные учреждения,  иные организации,  наделенные полномочиями главного администратора доходов федерального бюджета. (Дополнение абзацем - Федеральный закон от 22.10.2014 № 311-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nВнесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзаце четвертом настоящего пункта,  осуществляется в связи с принятием федеральных законов и (или)  нормативных правовых актов  Правительства  Российской Федерации,  обусловливающих установление новых либо изменение действующих источников доходов федерального бюджета,  бюджетов государственных внебюджетных фондов Российской Федерации,  бюджетов субъектов Российской Федерации,  бюджетов территориальных государственных внебюджетных фондов и местных бюджетов в связи с принятием федеральных законов,  регулирующих вопросы установления нормативов распределения доходов между бюджетами бюджетной системы Российской Федерации. (Дополнение абзацем - Федеральный закон от 04.08.2023 № 416-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nФинансовый орган субъекта Российской Федерации утверждает перечень кодов подвидов по видам доходов,  главными администраторами которых являются органы государственной власти субъектов Российской Федерации,  органы управления территориальными государственными внебюджетными фондами и (или)  находящиеся в их ведении казенные учреждения. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nФинансовый орган муниципального образования утверждает перечень кодов подвидов по видам доходов,  главными администраторами которых являются органы местного самоуправления и (или)  находящиеся в их ведении казенные учреждения. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 20. Классификация доходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"22efb538f3c7ed69dea9c6468ddd5c8ba9323356e5efd7bee4586610d88b521a"},{"code_id":"BK_RF","article_number":"21","version_date":"1998-07-31","article_text":"1. Код классификации расходов бюджетов состоит из:\n\n1)  кода главного распорядителя бюджетных средств;\n\n2)  кода раздела,  подраздела,  целевой статьи и вида расходов;\n\n3)  (Подпункт утратил силу - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n2. Перечень главных распорядителей средств федерального бюджета,  бюджета субъекта Российской Федерации,  бюджетов государственных внебюджетных фондов,  местного бюджета устанавливается законом (решением)  о соответствующем бюджете в составе ведомственной структуры расходов.\n\n3. Едиными для бюджетов бюджетной системы Российской Федерации разделами и подразделами классификации расходов бюджетов являются:\n\n1)  общегосударственные вопросы:\n\nфункционирование Президента Российской Федерации;\n\nфункционирование высшего должностного лица субъекта Российской Федерации и муниципального образования;\n\nфункционирование законодательных (представительных)  органов государственной власти и представительных органов муниципальных образований;\n\nфункционирование  Правительства  Российской Федерации,  высших исполнительных органов субъектов Российской Федерации,  местных администраций; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nсудебная система;\n\nобеспечение деятельности финансовых,  налоговых и таможенных органов и органов финансового (финансово-бюджетного)  надзора;\n\nобеспечение проведения выборов и референдумов;\n\nмеждународные отношения и международное сотрудничество;\n\nгосударственный материальный резерв;\n\nфундаментальные исследования;\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nрезервные фонды;\n\nприкладные научные исследования в области общегосударственных вопросов;\n\nдругие общегосударственные вопросы;\n\n2)  национальная оборона:\n\nВооруженные Силы Российской Федерации;\n\nредакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 21. Классификация расходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"48dbe8c06e6d873f6ca0122b25c054532b4c3a8254d92cc03d2dd6fd5d766384"},{"code_id":"BK_RF","article_number":"22","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 22.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"}]$law7d0010$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
